var root="Assets/Arkya/Totems/Prefabs/";
var actual=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(root+"wolf.prefab");
var reference=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(root+"wolf-lunar.prefab");
if(!actual || !reference) throw new System.InvalidOperationException("Missing default or reference prefab.");
var a=actual.GetComponentInChildren<UnityEngine.Animator>();
var b=reference.GetComponentInChildren<UnityEngine.Animator>();
var skins=actual.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>(true);
var refSkins=reference.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>(true);
var sameMeshes=skins.Select(s=>s.sharedMesh).SequenceEqual(refSkins.Select(s=>s.sharedMesh));
var sameMaterials=skins.SelectMany(s=>s.sharedMaterials).SequenceEqual(refSkins.SelectMany(s=>s.sharedMaterials));
var sameController=a && b && a.runtimeAnimatorController==b.runtimeAnimatorController;
var avatarValid=a && a.avatar && a.avatar.isValid && !a.avatar.isHuman;
var noMissingScripts=actual.GetComponentsInChildren<UnityEngine.Transform>(true).All(t=>UnityEditor.GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)==0);
var sameTransform=actual.transform.localScale==UnityEngine.Vector3.one && a.transform.localRotation==b.transform.localRotation && a.transform.localScale==b.transform.localScale;
var noColliders=actual.GetComponentsInChildren<UnityEngine.Collider>(true).Length==0;
var success=skins.Length==3 && sameMeshes && sameMaterials && sameController && avatarValid && noMissingScripts && sameTransform && noColliders && !a.applyRootMotion;
if(!success) throw new System.InvalidOperationException("Default wolf prefab differs from validated lunar appearance.");
return new {success,prefab=root+"wolf.prefab",reference=root+"wolf-lunar.prefab",sameMeshes,sameMaterials,sameController,avatarValid,noMissingScripts,sameTransform,noColliders,skinnedRenderers=skins.Length};
